        strategy = "aspiration_target"
    elif state["goal"] == "reassurance" or state["confidence"] < 0.60:
        strategy = "relatability_target"
    else:
        strategy = "growth_reference"

    # 3. Select a suitable anonymized aggregate/profile
    if strategy == "aspiration_target":
        # Close enough to be credible; modestly ahead to avoid discouragement.
        candidates = [
            p for p in eligible_peers
            if 0.05 <= p["skill_level"] - learner_profile["skill_level"] <= 0.15
            and p["recent_growth"] >= 0
        ]

        peer = select_best_match(
            candidates,
            keys=["shared_topic", "similar_prior_level", "realistic_gap"]
        )

        if peer is None:
